Your expense tracker is below. Add each spend with an amount and category, and it totals the month, shows where the money went and compares it with a budget you set. It tries to remember your entries on this PC, so check that they are still there when you reopen it.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<style>
*{box-sizing:border-box}
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#faf7f2;color:#222;font-size:14px}
h2{margin:0 0 10px;font-size:18px}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{font:inherit;padding:7px 9px;border:1px solid #c9c2b6;border-radius:6px;background:#fff}
input.grow{flex:1;min-width:120px}
button{background:#2f6f5e;color:#fff;border-color:#2f6f5e;cursor:pointer}
button.x{background:none;color:#a33;border:none;padding:2px 8px}
.card{background:#fff;border:1px solid #e4ddd0;border-radius:8px;padding:10px;margin-bottom:10px}
.stats{display:flex;gap:10px;flex-wrap:wrap}
.stat{flex:1;min-width:110px}
.stat b{display:block;font-size:18px}
.bar{height:8px;background:#eee;border-radius:4px;overflow:hidden;margin-top:4px}
.bar i{display:block;height:100%;background:#2f6f5e}
.bar.over i{background:#c0392b}
.cat{margin:6px 0}
.cat span{display:flex;justify-content:space-between}
.item{display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #eee}
.item .d{flex:1}
.item small{color:#777;display:block}
.empty{color:#888;padding:6px 0}
label{font-size:12px;color:#666}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <div><label>Month</label><br><input type="month" id="month"></div>
    <div><label>Budget (₹)</label><br><input type="number" id="budget" min="0" placeholder="e.g. 40000"></div>
  </div>
  <div class="stats">
    <div class="stat">Spent<b id="total">₹0</b></div>
    <div class="stat">Left<b id="left">-</b></div>
    <div class="stat">Entries<b id="count">0</b></div>
  </div>
  <div class="bar" id="bbar"><i style="width:0%"></i></div>
</div>

<div class="card">
  <div class="row">
    <input class="grow" id="desc" placeholder="What was it for?">
    <input type="number" id="amt" min="0" placeholder="Amount ₹" style="width:110px">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
    </select>
    <input type="date" id="date">
    <button type="button" id="add">Add expense</button>
  </div>
</div>

<div class="card">
  <b>Where it went</b>
  <div id="cats"></div>
</div>

<div class="card">
  <b>Entries</b>
  <div id="list"></div>
</div>

<script>
var K='foo-expenses-v1';
var d={items:[],budget:0};
try{var s=localStorage.getItem(K);if(s)d=JSON.parse(s);}catch(e){}
function save(){try{localStorage.setItem(K,JSON.stringify(d));}catch(e){}}
function $(id){return document.getElementById(id);}
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN');}
var today=new Date().toISOString().slice(0,10);
$('date').value=today;
$('month').value=today.slice(0,7);
if(d.budget)$('budget').value=d.budget;

function render(){
  var m=$('month').value;
  var items=d.items.filter(function(x){return x.date.slice(0,7)===m;})
    .sort(function(a,b){return a.date<b.date?1:-1;});
  var total=items.reduce(function(s,x){return s+x.amt;},0);
  $('total').textContent=inr(total);
  $('count').textContent=items.length;
  var b=Number(d.budget)||0;
  var bb=$('bbar');
  if(b>0){
    var left=b-total;
    $('left').textContent=(left<0?'-':'')+inr(Math.abs(left));
    $('left').style.color=left<0?'#c0392b':'#222';
    bb.className='bar'+(left<0?' over':'');
    bb.firstChild.style.width=Math.min(100,total/b*100)+'%';
  }else{
    $('left').textContent='-';
    $('left').style.color='#222';
    bb.className='bar';
    bb.firstChild.style.width='0%';
  }
  var by={};
  items.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt;});
  var cats=$('cats');cats.textContent='';
  var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a];});
  if(!keys.length){cats.innerHTML='<div class="empty">Nothing yet this month.</div>';}
  keys.forEach(function(k){
    var c=document.createElement('div');c.className='cat';
    var sp=document.createElement('span');
    var a=document.createElement('span');a.textContent=k;
    var v=document.createElement('span');
    v.textContent=inr(by[k])+' ('+Math.round(by[k]/total*100)+'%)';
    sp.appendChild(a);sp.appendChild(v);
    var bar=document.createElement('div');bar.className='bar';
    var i=document.createElement('i');i.style.width=(by[k]/total*100)+'%';
    bar.appendChild(i);c.appendChild(sp);c.appendChild(bar);cats.appendChild(c);
  });
  var list=$('list');list.textContent='';
  if(!items.length){list.innerHTML='<div class="empty">No entries for this month.</div>';}
  items.forEach(function(x){
    var r=document.createElement('div');r.className='item';
    var dd=document.createElement('div');dd.className='d';
    dd.textContent=x.desc||x.cat;
    var sm=document.createElement('small');sm.textContent=x.cat+' · '+x.date;
    dd.appendChild(sm);
    var am=document.createElement('b');am.textContent=inr(x.amt);
    var del=document.createElement('button');del.type='button';del.className='x';del.textContent='✕';
    del.title='Delete';
    del.onclick=function(){
      d.items=d.items.filter(function(y){return y.id!==x.id;});
      save();render();
    };
    r.appendChild(dd);r.appendChild(am);r.appendChild(del);list.appendChild(r);
  });
}

$('add').onclick=function(){
  var a=parseFloat($('amt').value);
  if(!(a>0)){$('amt').focus();return;}
  var dt=$('date').value||today;
  d.items.push({id:Date.now()+Math.random(),desc:$('desc').value.trim(),amt:a,cat:$('cat').value,date:dt});
  $('desc').value='';$('amt').value='';
  $('month').value=dt.slice(0,7);
  save();render();$('desc').focus();
};
$('amt').onkeydown=$('desc').onkeydown=function(e){if(e.key==='Enter')$('add').onclick();};
$('month').onchange=render;
$('budget').oninput=function(){d.budget=Number($('budget').value)||0;save();render();};
render();
</script>
</body>
</html>
```

Here's a water tracker with a goal of 8 glasses. Tap + after each glass, or tap a cup to set your count. It resets each day when you open it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: sans-serif; text-align: center; padding: 24px; background: #f1f8fc; color: #12344d; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  #count { font-size: 40px; font-weight: bold; margin: 12px 0 4px; }
  #msg { margin-bottom: 16px; min-height: 20px; }
  #cups { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 360px; margin: 0 auto 20px; }
  .cup { width: 64px; height: 80px; border: 3px solid #2a8fd0; border-radius: 4px 4px 14px 14px; background: #fff; cursor: pointer; }
  .cup.full { background: #5bb8ee; }
  button { font-size: 18px; padding: 10px 22px; margin: 0 6px; border: 0; border-radius: 8px; background: #2a8fd0; color: #fff; cursor: pointer; }
  button.alt { background: #8aa3b5; }
  #bar { height: 10px; max-width: 360px; margin: 0 auto 16px; background: #d6e8f3; border-radius: 5px; overflow: hidden; }
  #fill { height: 100%; width: 0; background: #2a8fd0; transition: width .3s; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="cups"></div>
  <button onclick="change(1)">+ Glass</button>
  <button class="alt" onclick="change(-1)">- Undo</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = today;

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function change(d) {
    n = Math.max(0, Math.min(20, n + d));
    save();
    draw();
  }

  function setTo(i) {
    n = (n === i + 1) ? i : i + 1;
    save();
    draw();
  }

  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
    var box = document.getElementById("cups");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var c = document.createElement("div");
      c.className = "cup" + (i < n ? " full" : "");
      c.onclick = (function (k) { return function () { setTo(k); }; })(i);
      box.appendChild(c);
    }
  }
  draw();
</script>
</body>
</html>
```
